SELECT c.name, o.id
FROM customers c
LEFT JOIN orders o ON o.customer_id = c.id;

SELECT name, price * qty AS total
FROM order_items
WHERE total > 100;

SELECT COUNT(*)
FROM orders
WHERE shipped_at = NULL;

-- User 42 asked to close their account
UPDATE users
SET active = false;
WHERE id = 42;

SELECT COUNT(*)
FROM people
WHERE name LIKE 'Jo%';
